def C__prefill_opt_sub_iox2(lhs, rhs, IO_DTYPE):
    result = txl.local_scalar("uint32")
    if IO_DTYPE == "float16":
        txl.ptx.sub.f16x2(result, lhs, rhs)
    else:
        txl.ptx["sub.bf16x2"](result, lhs, rhs)
    return result


