                    p_v.full.wait(st_v.stage, st_v.phase)
                    v_words = txl.alloc_local((32,), "uint32")
                    C__prefill_opt_load_v_fragment(s_v, st_v.stage, cg1_thread, v_words)
                    p_cg1.full.wait(st_shared.stage, st_shared.phase)
